import fs from 'node:fs/promises';import{db}from'./reply-runtime-20261015.mjs';import{deliveryExposure}from'./realtor-delivery-exposure-20261019.mjs';
const dir='artifacts/realtor-batch-20261019';const live=JSON.parse(await fs.readFile(dir+'/live-status.json'));if(Date.parse(live.summary.at)<Date.now()-120000)throw Error('Refresh receipts before restoring reserves');const exposure=deliveryExposure(live.jobs,live.events,2000);if(!exposure.available)process.exit(0);
const candidates=live.jobs.filter(j=>j.status==='cancelled'&&!j.provider_sid&&j.last_error==='excess_exposure_cancelled_20261019').slice(0,exposure.available);if(!candidates.length)process.exit(0);
const balanceResponse=await fetch('https://api.telnyx.com/v2/balance',{headers:{Authorization:'Bearer '+process.env.TELNYX_API_KEY.trim()}});if(!balanceResponse.ok)throw Error('Funding check failed');const balance=Number((await balanceResponse.json()).data.balance);const pending=live.jobs.filter(j=>!j.provider_sid&&['pending','running'].includes(j.status)).length;if(balance<8+(pending+candidates.length)*0.091)throw Error('Conservative reserve funding hold');
let restored=0;
for(const j of candidates){const [c]=await db('market_contacts',{id:'eq.'+j.contact_id});const[touches,reservations,tasks]=await Promise.all([db('market_touches',{contact_id:'eq.'+j.contact_id,select:'id',limit:'1'}),db('partnership_action_reservations',{contact_id:'eq.'+j.contact_id,select:'action_key',limit:'1'}),db('crm_tasks',{related_id:'eq.'+j.contact_id,status:'in.(open,in_progress)',select:'id',limit:'1'})]);if(!c||c.do_not_contact||c.cross_channel_suppressed_at||c.sequence_paused||c.last_inbound_at||c.last_touch_at||c.phone!==j.sms_payload.to||touches.length||reservations.length||tasks.length)continue;
 const rows=await db('sequence_jobs',{id:'eq.'+j.id,status:'eq.cancelled',provider_sid:'is.null',last_error:'eq.excess_exposure_cancelled_20261019'},'PATCH',{status:'pending',error:null,last_error:null,scheduled_at:new Date(Date.now()+180000+restored*2000).toISOString()});if(rows.length===1){restored++;await fs.appendFile(dir+'/restored-fresh-reserves.jsonl',JSON.stringify({at:new Date().toISOString(),id:j.id,contact_id:j.contact_id,exposure})+'\n');}
}
console.log(JSON.stringify({available:exposure.available,restored}));
